+        checkRequiredArgument(serverArgs, "serverArgs");
+        checkRequiredArgument(processInfo, "processInfo");
+        checkRequiredArgument(jvmOptions, "jvmOptions");
+        checkRequiredArgument(terminal, "terminal");
